from collections import Counter

def transform(grid):
    """Fill gaps between consecutive occurrences of the rare marker in each row and column."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out

